SELECT 'SOURCE_LEDGER' key,
'RELATIONSHIP_ID'||'~'||'SOURCE_LEDGER_ID'||'~'||'TARGET_LEDGER_ID'||'~'||'SLA_LEDGER_ID'||'~'||'PRIMARY_LEDGER_ID'||'~'||'TARGET_CURRENCY_CODE'||'~'||
'TARGET_LEDGER_NAME'||'~'||'TARGET_LEDGER_SHORT_NAME'||'~'||'TARGET_LEDGER_CATEGORY_CODE'||'~'||'RELATIONSHIP_TYPE_CODE'||'~'||
'RELATIONSHIP_ENABLED_FLAG'||'~'||'INHERIT_CREATION_USER_FLAG'||'~'||'AUTOMATIC_POST_FLAG'||'~'||'ALC_NO_RATE_ACTION_CODE'||'~'||
'ALC_INHERIT_CONVERSION_TYPE'||'~'||'ALC_INIT_DATE'||'~'||'ALC_INITIALIZING_RATE_DATE'||'~'||'APPLICATION_ID'||'~'||'ORG_ID'||'~'||'DISABLE_CONVERSION_DATE'||'~'||
'CREATION_DATE'||'~'||'CREATED_BY'||'~'||'LAST_UPDATE_DATE'||'~'||'LAST_UPDATED_BY'||'~'||'LAST_UPDATE_LOGIN'||'~'||'OBJECT_VERSION_NUMBER'||'~'||
'GL_JE_CONVERSION_SET_ID'||'~'||'ALC_DEFAULT_CONV_RATE_TYPE'||'~'||'ALC_INIT_CONV_OPTION_CODE'||'~'||'ALC_INIT_PERIOD'||'~'||
'ALC_INITIALIZING_RATE_TYPE'||'~'||'ALC_PERIOD_END_RATE_TYPE'||'~'||'STATUS_CODE'||'~'||'REV_EXP_XLATION_RULE_CODE'||'~'||'OE_XLATION_RULE_CODE' LEDGER_RELATIONSHIPS
FROM DUAL 
UNION ALL
SELECT 'SOURCE_LEDGER' key,
RELATIONSHIP_ID||'|'||SOURCE_LEDGER_ID||'|'||TARGET_LEDGER_ID||'|'||SLA_LEDGER_ID||'|'||PRIMARY_LEDGER_ID||'|'||TARGET_CURRENCY_CODE||'|'||
TARGET_LEDGER_NAME||'|'||TARGET_LEDGER_SHORT_NAME||'|'||TARGET_LEDGER_CATEGORY_CODE||'|'||RELATIONSHIP_TYPE_CODE||'|'||
RELATIONSHIP_ENABLED_FLAG||'|'||INHERIT_CREATION_USER_FLAG||'|'||AUTOMATIC_POST_FLAG||'|'||ALC_NO_RATE_ACTION_CODE||'|'||
ALC_INHERIT_CONVERSION_TYPE||'|'||ALC_INIT_DATE||'|'||ALC_INITIALIZING_RATE_DATE||'|'||APPLICATION_ID||'|'||ORG_ID||'|'||DISABLE_CONVERSION_DATE||'|'||
CREATION_DATE||'|'||CREATED_BY||'|'||LAST_UPDATE_DATE||'|'||LAST_UPDATED_BY||'|'||LAST_UPDATE_LOGIN||'|'||OBJECT_VERSION_NUMBER||'|'||
GL_JE_CONVERSION_SET_ID||'|'||ALC_DEFAULT_CONV_RATE_TYPE||'|'||ALC_INIT_CONV_OPTION_CODE||'|'||ALC_INIT_PERIOD||'|'||
ALC_INITIALIZING_RATE_TYPE||'|'||ALC_PERIOD_END_RATE_TYPE||'|'||STATUS_CODE||'|'||REV_EXP_XLATION_RULE_CODE||'|'||OE_XLATION_RULE_CODE
FROM GL_LEDGER_RELATIONSHIPS a
WHERE ((:P_FROM_DATE IS NOT NULL AND :P_TO_DATE IS NOT NULL AND a.last_update_date between :P_FROM_DATE AND :P_TO_DATE) or
			(:P_FROM_DATE IS NULL AND :P_TO_DATE IS NULL AND  a.last_update_date  > (SELECT MAX(ERH.processstart)
                                         FROM ess_request_history ERH
                                             ,ess_request_property ERP
                                        WHERE ERH.requestid = ERP.requestid
                                          AND ERH.definition = 'JobDefinition://oracle/apps/ess/custom/cclf/CCLF_DL_GL_Relationships'
                                          AND ERH.executable_status = 'SUCCEEDED'
                                          AND ERP.name = 'submit.argument3'
                             	          AND ERP.value IS NOT NULL)))